      /* (2575) values_row_nested_tokens ::= */ yytestcase(yyruleno==2575);
      /* (2588) values_query_tail ::= */ yytestcase(yyruleno==2588);
      /* (2596) values_into_optional_tail ::= */ yytestcase(yyruleno==2596);
      /* (2602) values_limit_optional_tail ::= */ yytestcase(yyruleno==2602);
      /* (2622) values_order_direction ::= */ yytestcase(yyruleno==2622);
