      /* (2637) diagnostics_area_tail ::= */ yytestcase(yyruleno==2637);
      /* (2680) signal_sqlstate_value_tail ::= */ yytestcase(yyruleno==2680);
      /* (2683) signal_set_tail ::= */ yytestcase(yyruleno==2683);
